```yaml
name: PR Issue Link Check

on:
  pull_request:
    types: [opened, synchronize, reopened]

jobs:
  check-issue-link:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4
        with:
          fetch-depth: 0

      - name: Check PR issue links
        uses: actions/github-script@v6
        with:
          script: |
            const patterns = [
              /Fixes\s+#(\d+)/gi,
              /Closes\s+#(\d+)/gi,
              /Resolves\s+#(\d+)/gi,
              /Fix\s+#(\d+)/gi,
              /Resolve\s+#(\d+)/gi,
              /Close\s+#(\d+)/gi
            ];

            const pr = context.payload.pull_request;
            const repo = context.repo;
            const issueNumbers = new Set();

            const extract = (text) => {
              if (!text) return;
              for (const pat of patterns) {
                let m;
                while ((m = pat.exec(text)) !== null) {
                  issueNumbers.add(m[1]);
                }
              }
            };

            extract(pr.title);
            extract(pr.body);

            const commits = await github.rest.pulls.listCommits({
              owner: repo.owner,
              repo: repo.repo,
              pull_number: pr.number
            });

            for (const commit of commits.data) {
              extract(commit.commit.message);
            }

            if (issueNumbers.size === 0) {
              core.setFailed('No issue references found in PR title, body, or commit messages. Please reference an issue using "Fixes #123", "Closes #456", or "Resolves #789".');
            }

            for (const num of issueNumbers) {
              try {
                await github.rest.issues.get({
                  owner: repo.owner,
                  repo: repo.repo,
                  issue_number: parseInt(num, 10)
                });
              } catch (error) {
                core.setFailed(`Referenced issue #${num} does not exist in this repository.`);
              }
            }
